/**
 * The pack's mark, embedded rather than fetched.
 *
 * `generate()` is synchronous — it builds the whole document and returns a
 * jsPDF instance — so the logo cannot be loaded over the network at render
 * time without making every caller async, including the headless preview
 * harness, which has no network to load it from. Embedding is the smaller
 * change and the one that works everywhere the service already works.
 *
 * Two marks, because they do different jobs. The stacked lockup is the cover's
 * — it is the first thing a client sees and it should say the whole name. The
 * horizontal one is the page corner's, where the reference pack puts its own
 * and where a stacked mark would be unreadable at 12mm.
 *
 * Source files are public/images/logo-tight.png and logo-wbi.png. If the brand
 * changes, regenerate both constants from those.
 */

/** Horizontal WBi mark, 410x170. The page corner. */
export const LOGO_CORNER = 'data:image/png;base64,'
/** Stacked Wisdom BI lockup, 550x300. The cover. */
export const LOGO_COVER = 'data:image/png;base64,'

/** Native pixel dimensions, so callers scale rather than guess an aspect. */
export const LOGO_CORNER_SIZE = { w: 410, h: 170 }
export const LOGO_COVER_SIZE = { w: 550, h: 300 }
